using System.ComponentModel.DataAnnotations;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.AspNetCore.Mvc.Rendering;using Microsoft.EntityFrameworkCore;using NoryMusicLMS_VS.Data;using NoryMusicLMS_VS.Models;using NoryMusicLMS_VS.Services;
namespace NoryMusicLMS_VS.Areas.Admin.Pages.Quizzes;
[Authorize(Roles="Admin")] public class CreateModel:PageModel{private readonly ApplicationDbContext _db;private readonly ImageStorageService _images;public CreateModel(ApplicationDbContext db,ImageStorageService images){_db=db;_images=images;}[BindProperty]public QuizInput Input{get;set;}=new();public class QuizInput{[Required,StringLength(100)]public string Title{get;set;}="";[StringLength(500)]public string Description{get;set;}="";public QuizType Type{get;set;}=QuizType.Theory;[Required]public int LessonId{get;set;}public bool IsActive{get;set;}=true;public IFormFile? Image{get;set;}}
public async Task<IActionResult> OnGetAsync(){await LoadLessonsAsync();return Page();}public async Task<IActionResult> OnPostAsync(){var lesson=await _db.Lessons.Include(l=>l.Course).FirstOrDefaultAsync(l=>l.Id==Input.LessonId&&l.Course.IsActive);if(lesson is null)ModelState.AddModelError("Input.LessonId","Select a lesson from an active course.");if(ImageStorageService.Validate(Input.Image) is{ }e)ModelState.AddModelError("Input.Image",e);if(!ModelState.IsValid){await LoadLessonsAsync();return Page();}var url=await _images.ApplyAsync(null,Input.Image,false,null);_db.Quizzes.Add(new Quiz{LessonId=lesson!.Id,Title=Input.Title.Trim(),Description=Input.Description.Trim(),Type=Input.Type,IsActive=Input.IsActive,ImageUrl=url,CreatedAt=DateTime.UtcNow});await _db.SaveChangesAsync();TempData["StatusMessage"]="Quiz created. Add questions next.";return RedirectToPage("./Index");}private async Task LoadLessonsAsync()=>ViewData["LessonId"]=new SelectList(await _db.Lessons.Include(l=>l.Course).Where(l=>l.Course.IsActive).OrderBy(l=>l.Course.Title).ThenBy(l=>l.OrderIndex).Select(l=>new{l.Id,Label=l.Course.Title+" — "+l.OrderIndex+". "+l.Title}).ToListAsync(),"Id","Label",Input.LessonId);}
